    if (!cursor) {
      return Promise.resolve(
        new Response(
          JSON.stringify({ result: [], result_info: { is_truncated: true, cursor: "page-2" } }),
          { status: 200 },
        ),
      );
    }
    return Promise.resolve(
      new Response(
        JSON.stringify({
          result: [
